 static Dictionary<string,string> Hashes(int i,string stage){string folder=Root+"/Fighter-"+i,snapshot=Output+"/idempotence/fighter-"+i+"/"+stage;Directory.CreateDirectory(snapshot);var names=new[]{"Review.exact-generic-anatomic-v4.prefab","Dance.generic.source.pose.asset","Dance.generic.source.pose.asset.curves.bytes","Dance.generic.clock.anim","GenericV4.controller"};return names.Concat(names.Select(n=>n+".meta")).ToDictionary(n=>n,n=>{byte[] bytes=File.ReadAllBytes(folder+"/"+n);File.WriteAllBytes(snapshot+"/"+n,bytes);return Hash(bytes);});}
 static string Hash(byte[] b){using(var sha=SHA256.Create())return BitConverter.ToString(sha.ComputeHash(b)).Replace("-","").ToLowerInvariant();}
